// priority: 9050
// Gregtech Grindless - EMI information pages of the IV era multiblocks (kubejs/assets/emi/recipe/additions/grindless/<id>.json, type emi:info).
// One page per controller: what it does, what it is for, what it needs. Their recipes show in EMI under the controller itself.
// Tooltips live in the iv_*_lang.js files; every key is in en_us and es_es.
ClientEvents.lang('en_us', event => {
    var add = function (key, value) { event.add('grindless', key, value) }

    add('emi.grindless.info.fission_reactor.0', "The Fission Reactor turns nuclear fuel into EU and heat. Circuit 1: low-enriched uranium with light water. Circuit 2: the same fuel with heavy water. Circuit 3: MOX with heavy water. Circuit 4: breeder, which makes plutonium.")
    add('emi.grindless.info.fission_reactor.1', "If its output has nowhere to go the reactor does a SCRAM: it stops safely instead of voiding. Spent fuel goes to the Hot Cell for reprocessing.")
    add('emi.grindless.info.fission_reactor.2', "A designed-core fission reactor: fuel assemblies in four tungstensteel channels boil water for a turbine hall. Nothing burns, so it works anywhere. The programmed circuit picks the core: 1 LEU in light water, 2 LEU in heavy water, 3 MOX in heavy water, 4 breeder.")
    add('emi.grindless.info.fission_reactor.3', "Per channel and 20 s cycle: 2,000 mB of water, lost through the vents. LEU in light water makes 16,384 EU/t; in heavy water 32,768, and 5 mB of heavy water comes out tritiated; MOX in heavy water the same; the breeder 8,192, and its spent assembly holds more plutonium than went in.")
    add('emi.grindless.info.fission_reactor.4', "An assembly wears 0.5% a cycle: one is used up, and one spent assembly comes out, every 200 channel-cycles (about 67 min in one channel). Channels = the fewest of 4, the assemblies in the buses, the water and heavy water, the room for the outputs and the dynamo hatches (a heavy-water channel needs 32,768 EU/t: a 4 A IV hatch; a 16 A IV hatch carries all four).")
    add('emi.grindless.info.fission_reactor.5', "SCRAM, not explosion: with no water, or no room for the spent fuel or the tritiated heavy water, it finishes its cycle and shuts down, losing nothing; it refuses voiding. Turbine hall floor: 1-2 input buses, 1-2 output buses, 1-3 fluid input hatches, up to 1 fluid output hatch and 1-4 dynamo hatches. ME parts fit.")

    add('emi.grindless.info.fluorspar_kiln.0', "The Fluorspar Kiln heats fluorspar with sulfuric acid and water into hydrofluoric acid and gypsum. It is where the hydrofluoric acid of the nuclear line comes from.")
    add('emi.grindless.info.fluorspar_kiln.1', "Gypsum is a harmless byproduct: it can be voided or used for building.")
    add('emi.grindless.info.fluorspar_kiln.2', "A long rotary kiln on roller stands, turned by a gearbox, with an HF scrubber at its hot end. Fluorspar, sulfuric acid and water go in at the cold end: hydrofluoric acid leaves the scrubber, and the calcium sulfate is quenched with the water and drops out as gypsum. The unreacted fluorite goes back to the feed.")
    add('emi.grindless.info.fluorspar_kiln.3', "It runs many charges at once, each at the recipe's own power and time, with no overclock: as many as the inputs, the room and the energy hatches allow, up to 256. One IV energy hatch runs all 256.")
    add('emi.grindless.info.fluorspar_kiln.4', "The HF feeds the naquadah plant, the hot cell's enrichment and PTFE; the gypsum goes to concrete. The scrubber keeps every drop of HF: the kiln refuses to void fluids. Surplus gypsum is inert and can be voided.")
    add('emi.grindless.info.fluorspar_kiln.5', "Feed head, round the controller: 1-2 energy hatches, 1-2 input buses and 1-4 input hatches (acid and water). Scrubber, the two lower rows of its back wall and the row under the kiln: 1-2 output buses and 1-2 output hatches. ME parts fit.")

    add('emi.grindless.info.fuel_fabrication_plant.0', "The Fuel Fabrication Plant builds fuel assemblies. Circuit 1: fuel pellets. Circuit 2: cladding tubes. Circuit 3: the low-enriched uranium fuel assembly the Fission Reactor burns.")
    add('emi.grindless.info.fuel_fabrication_plant.1', "It is the step between enriched uranium and the reactor.")
    add('emi.grindless.info.fuel_fabrication_plant.2', "Real fuel: uranium dioxide pellets in Zircaloy tubes, backfilled with helium. The programmed circuit picks the step: 1 pellets, 2 cladding tubes, 3 the LEU fuel assembly.")
    add('emi.grindless.info.fuel_fabrication_plant.3', "1: 1 U-235 + 9 U-238 dust + 20,000 mB of oxygen -> 10 LEU pellets, pressed and sintered in hydrogen. Keep 500 mB of hydrogen in a hatch: it goes round inside the furnace and is never used up.")
    add('emi.grindless.info.fuel_fabrication_plant.4', "2: 1 Zircaloy ingot -> 2 cladding tubes on the pilger mill. 3: 10 pellets + 4 tubes + 100 mB of helium -> 1 LEU fuel assembly, the fission reactor's fuel.")
    add('emi.grindless.info.fuel_fabrication_plant.5', "A 3x4x13 line of clean stainless steel casing: pellet press, sintering tunnel with two rings of Kanthal or hotter coils, pilger stand on a tungsten steel frame bed and a laminated glass glovebox. Floor of the press bay and the glovebox: 1-3 input buses, 1-2 output buses, 1-4 fluid input hatches and 1-2 energy hatches. ME parts fit.")

    add('emi.grindless.info.heavy_water_plant.0', "The Heavy Water Plant concentrates deuterium out of water. Circuit 1: isotope exchange. Circuit 2: finishing into heavy water. Circuit 3: Proxima mode, from UHV.")
    add('emi.grindless.info.heavy_water_plant.1', "It needs a hydrogen sulfide charge to run the exchange. Heavy water feeds the Fission Reactor and the tritium line.")
    add('emi.grindless.info.heavy_water_plant.2', "A Girdler sulfide plant: a cold tower and a taller hot tower joined by a heat-exchanger bridge, and a vacuum column. Martian deuterium-rich ice goes in as dust and is melted inside. The programmed circuit picks the mode: 1 exchange, 2 finishing, 3 exchange of Proxima b's deuterium-enriched water (UHV).")
    add('emi.grindless.info.heavy_water_plant.3', "Exchange: 16 ice and 25,600 mB of steam give 3,200 mB of heavy-water concentrate, 12,800 mB of depleted water and 160 mB of distilled water. It needs a 1,000 mB hydrogen sulfide charge in an input hatch of its own: the charge circulates between the towers and is never used up.")
    add('emi.grindless.info.heavy_water_plant.4', "Finishing: 1,000 mB of concentrate gives 200 mB of heavy water and 800 mB of distilled water. One ice makes 40 mB of heavy water: the fission reactor's moderator, and 80 mB of deuterium in the electrolyzer.")
    add('emi.grindless.info.heavy_water_plant.5', "The towers' feet take 1-2 energy hatches, 1-2 input buses, 1-4 input hatches and 1-4 output hatches; ME parts fit. The steam comes from plants that never void theirs: the combined-cycle plant and the hot strip mill. The depleted water is plain water.")

    add('emi.grindless.info.hot_cell.0', "The Hot Cell handles radioactive material behind shielding. Circuit 1: enrichment. 2: fuel. 3: reprocessing of spent fuel. 4: radon. 5: silicon-28. 6: boron-11. 7: nickel-62.")
    add('emi.grindless.info.hot_cell.1', "It refuses to void: if an output is blocked it stops. Reprocessing is how spent fuel gives something back.")
    add('emi.grindless.info.hot_cell.2', "A bank of two shielded cells: radioactive material comes in through buses and hatches and leaves to the network, never through hands. Tongs through the wall above each lead-glass window do the work. The programmed circuit picks the mode: 1 enrichment, 2 fuel, 3 reprocessing, 4 radon, 5 silicon-28, 6 boron-11, 7 nickel-62.")
    add('emi.grindless.info.hot_cell.3', "Modes 1 and 4 run GregTech's own lines in one pass, with the same energy: enrichment turns 30 uraninite and 40,000 mB of HF into 1 U-235, 9 U-238, water and the same fluorine as F2, and the UF6 never leaves; radon needs no plutonium, because GregTech's plutonium catalyst stays inside.")
    add('emi.grindless.info.hot_cell.4', "Mode 2 makes MOX and breeder assemblies in Zircaloy tubes, RTG pellets and Pu-Be neutron sources. Mode 3 reprocesses spent assemblies in nitric acid: the uranium and plutonium come back, with xenon, krypton, caesium, neodymium, NO2 for nitric acid and glassed waste.")
    add('emi.grindless.info.hot_cell.5', "The waste is contained: it leaves through the output bus, and the hot cell refuses voiding. Service wall and side walls: 1-2 energy hatches, 1-3 input buses, 1-3 output buses, 1-4 input hatches and 1-4 output hatches. ME parts fit.")

    add('emi.grindless.info.interferometer.0', "The Interferometer is a telescope array on Mercury that works only at night. It writes the Outer System Chart onto data sticks and orbs.")
    add('emi.grindless.info.interferometer.1', "It is the only source of that chart. At dawn it waits and keeps its progress.")
    add('emi.grindless.info.interferometer.2', "Three tungsten steel dishes on brick pedestals, joined by a cable run to a correlator hut: a radio interferometer on Mercury, with the Moon's Deep Space Antenna at the far end of its baseline.")
    add('emi.grindless.info.interferometer.3', "Works only on Mercury, at night. If dawn comes mid-run, it waits and keeps its progress.")
    add('emi.grindless.info.interferometer.4', "It adds Mercury's half to a Lunar VLBI Recording and writes the Outer System Chart (calibrated by the Inner Planets Chart, never used up) or, calibrated by the Outer System Chart, the first signal of Sagittarius A*.")
    add('emi.grindless.info.interferometer.5', "Needs, in the correlator hut: 1 or 2 energy hatches (IV), 1 input bus and 1 output bus.")

    add('emi.grindless.info.isr_wellfield.0', "The ISR Wellfield leaches uranium in place on the End: sulfuric acid and oxygen go down the wells and uraninite comes up.")
    add('emi.grindless.info.isr_wellfield.1', "It works only on the End. The uraninite feeds the uranium line toward enrichment.")
    add('emi.grindless.info.isr_wellfield.2', "Uranium with no drill bit: sulfuric acid and oxygen go down four injection wells, dissolve the uranium of the End's pitchblende vein in place, and the production well brings it up to the header house, where ion exchange catches it. Works only in the End.")
    add('emi.grindless.info.isr_wellfield.3', "Each batch: the vein sample (never used up) + 100 mB of sulfuric acid + 50 mB of oxygen, and the ion-exchange resin wears 1% -> 2 uraninite dust. Thorium and lead stay in the ground.")
    add('emi.grindless.info.isr_wellfield.4', "The radium the solution carries comes out as radioactive waste (1% of the batches): it is contained, so the field refuses item voiding.")
    add('emi.grindless.info.isr_wellfield.5', "A 7x7 five-spot: wells of tungstensteel pipe casing three blocks into the ground, under PTFE pipe wellheads with a tungsten steel frame on top, and a header house of inert casing with two ion-exchange columns. House walls: 1-2 input buses, 1-2 output buses, 1-3 fluid input hatches and 1-2 energy hatches. ME parts fit.")

    add('emi.grindless.info.mercury_solar_field.0', "The Mercury Solar Field turns Mercury's sunlight into EU. Put programmed circuit 1 in the input bus.")
    add('emi.grindless.info.mercury_solar_field.1', "It works only on Mercury and only by day; at night it waits and loses nothing. Its EU leaves through dynamo hatches.")
    add('emi.grindless.info.mercury_solar_field.2', "36 Hermean Thin-Film Panels on tungsten steel posts over heat-shield bricks, a radiator bank behind them and the control hut under a brick sunshade. Sunlight straight into EU.")
    add('emi.grindless.info.mercury_solar_field.3', "Works only by day, on Mercury (x6.7 sunlight: 2,010 EU/t per panel). Each of its 36 panels with open sky above it adds a run: 72,360 EU/t. At night it waits, losing nothing.")
    add('emi.grindless.info.mercury_solar_field.4', "Put programmed circuit 1 in the input bus. Runs = the fewest of the lit panels and what the dynamo hatches carry (an IV dynamo hatch carries 16,384 EU/t: 8 panels; three IV 4A hatches carry the whole field).")
    add('emi.grindless.info.mercury_solar_field.5', "Needs, in the control hut: 1 input bus and 1 to 4 dynamo hatches. At night, use buffers or the power of home through the AE2 bridge.")

    add('emi.grindless.info.mercury_solar_works.0', "The Mercury Solar Works is the factory of the planet. It sinters heat-shield bricks, makes thin-film solar panels and fuses iridosmine.")
    add('emi.grindless.info.mercury_solar_works.1', "It works only on Mercury. The bricks line Mercury structures; the iridosmine goes to the Platinum Plant.")
    add('emi.grindless.info.mercury_solar_works.2', "Mercury's site workshop: eight heliostat mirrors focus the sun on a focal furnace of robust tungsten steel, with a laminated glass evaporation bell beside it. It works only on Mercury.")
    add('emi.grindless.info.mercury_solar_works.3', "It sinters Hermean regolith dust into heat-shield bricks, evaporates gallium arsenide onto silicon wafers into thin-film panels, and fuses iridosmine with saltpeter and salt water into rarest metal mixture and osmium tetroxide (3 iridium to 1 osmium, refined at home).")
    add('emi.grindless.info.mercury_solar_works.4', "Sun rule: a run that starts with the sun on the receiver and all eight mirrors under open sky pays a quarter of its EU/t; at night or shaded it pays all of it. Cheaper, never faster.")
    add('emi.grindless.info.mercury_solar_works.5', "Needs 1 or 2 energy hatches, 1 or 2 input buses, 1 or 2 output buses, up to 1 input hatch and up to 2 output hatches. It makes the bricks, so its pad is Mercury rock. While it voids fluids, the fusion does not run: the osmium tetroxide is kept.")

    add('emi.grindless.info.mercury_vein_drill.0', "The Mercury Vein Drill drills the veins of Mercury, only there, and never an Earth vein. Put the sample and tungsten steel drill bits in the input bus.")
    add('emi.grindless.info.mercury_vein_drill.1', "Liquid nitrogen in the input hatch gives more ore and less bit wear by day.")
    add('emi.grindless.info.mercury_vein_drill.2', "Mercury's vein drill: a low body of heat-shield bricks under a brick sunshade on four tungsten steel posts, with radiators hanging under the shade and a drill string down into the crust. It only drills Mercury's veins, and only on Mercury.")
    add('emi.grindless.info.mercury_vein_drill.3', "Tungsten steel drill bit, 5.625 raw ores per run. By day it only runs with liquid nitrogen (10 mB per run, the bit worn out in about 0.25% of the runs): Mercury's sun would burn a dry bit out. At night it drills dry and keeps the nitrogen, but the bit wears twice as fast (0.5%).")
    add('emi.grindless.info.mercury_vein_drill.4', "Runs as many bores at once as its energy hatches allow (voltage / 8 EU/t, up to 128, one bit per bore): one IV hatch fills all 128 and halves the time. Day or night is read when each run starts, so dawn and dusk never stop a run halfway.")
    add('emi.grindless.info.mercury_vein_drill.5', "Needs 1 or 2 energy hatches, 1 input bus (sample and bits), 1 or 2 output buses and 1 input hatch for the liquid nitrogen; ME buses and hatches fit. It stands on Hermean Heat-Shield Bricks.")

    add('emi.grindless.info.naquadah_plant.0', "The Naquadah Plant refines naquadah. Circuit 1 runs the naquadah line; circuits 2 and 3 are LuV modes.")
    add('emi.grindless.info.naquadah_plant.1', "It needs a plutonium-beryllium neutron source. Its products feed the dense materials of the next eras.")
    add('emi.grindless.info.naquadah_plant.2', "GT--'s naquadah line in one plant. Its neutron activator only makes naquadah while its neutron energy sits in a narrow window, kept with accelerators and a sensor; here a Pu-Be neutron source on the input bus holds the window, and the fluoroantimonic acid, the strongest superacid known, is made and used inside.")
    add('emi.grindless.info.naquadah_plant.3', "Circuit 1: 4 naquadah oxide mixture, 15 antimony trioxide and 40,500 mB of hydrofluoric acid give 2 naquadah dust, titanium and gallium (each in half the batches), 10,500 mB of hydrogen and 9,000 mB of water. The Pu-Be source wears out in 1% of the batches.")
    add('emi.grindless.info.naquadah_plant.4', "Same ratios and same energy as GT--'s machines, the accelerators' upkeep included (about 1.14 million EU a batch), spent at up to 7,680 EU/t; modes 2 and 3 at up to 30,720 EU/t (LuV).")
    add('emi.grindless.info.naquadah_plant.5', "Superacid hall: 1-2 energy hatches (two EV hatches run it until Mercury's iridium makes IV hatches), 1-2 input buses, 1-2 output buses, 1-6 input hatches and 1-4 output hatches in its edges; the activation chamber of radiation-proof casing stands at its side. ME parts fit.")
    add('emi.grindless.info.naquadah_plant.6', "LuV, circuit 2: 4 enriched naquadah oxide mixture, 36,000 mB of fluorine, 26,500 mB of hydrogen and 8,000 mB of sulfuric acid give enriched naquadah sulfate, 2 trinium sulfide, impure naquadria solution, titanium and HF. Xenon, fluoroantimonic acid, gold trifluoride and the Pd/C catalyst stay in the hatches and the bus as charges. Circuit 3 does the same with 6 naquadah dust from spent reactor rods. Neither voids its outputs.")

    add('emi.grindless.info.pressurized_vein_drill.0', "The Pressurized Vein Drill drills the naquadah vein of Venus and the veins of Mars, each only in its own world.")
    add('emi.grindless.info.pressurized_vein_drill.1', "It is the drill for places where the EV tripod drill cannot stand the pressure.")
    add('emi.grindless.info.pressurized_vein_drill.2', "The IV step of the vein drill family, for Venus and Mars: a closed shaft against 92 bar, jacketed in tungstensteel, under a pressure housing of inert casing and a deck of dust filters. Up to 128 runs at once, one Tungstensteel drill bit per run in the input bus (0.25% wear a run).")
    add('emi.grindless.info.pressurized_vein_drill.3', "Venus: the naquadah vein, deep under the lava seas. Each run: the vein sample (never used up) + 200 mB of distilled water, the heat tax -> 5.625 raw ores, Venus cobblestone and 1,600 mB of steam. The steam is inert: send it to a turbine through an output hatch, or set the controller to void fluids.")
    add('emi.grindless.info.pressurized_vein_drill.4', "Mars: its three veins, dry, because the dust filters keep the bit clean. Each run: the vein sample + the bit -> 5.625 raw ores and Martian cobblestone. It drills nothing anywhere else.")
    add('emi.grindless.info.pressurized_vein_drill.5', "5x9x4: a 5x4 pad of Venusian regolith on solid ground round a tungstensteel pipe drill string, a 3x3x3 housing of inert casing, a 3x3 deck of filter casings and a tungsten steel frame on top of the string. Housing: 1-2 energy hatches, 1 input bus, 1-2 output buses, up to 1 input hatch and up to 1 output hatch. ME parts fit.")

    add('emi.grindless.info.smelting_complex.0', "The Smelting Complex is a blast furnace and a vacuum freezer in one. It runs blast furnace recipes and the freezer step in a single pass.")
    add('emi.grindless.info.smelting_complex.1', "Its coils set how many copies run at once, so it is the high-throughput way to make alloy ingots.")
    add('emi.grindless.info.smelting_complex.2', "A blast furnace and a vacuum freezer in one hall: a coil chamber for the heat, a cold chamber for the cooling, a tungstensteel bulkhead between them. One recipe per blast furnace recipe that makes a hot ingot, with the freezer step folded in: dusts and gas in, the cooled ingot, the byproducts and the coolant's return gas out.")
    add('emi.grindless.info.smelting_complex.3', "The coils set the parallels (2^(coil temperature / 900), up to 64) and GTM's blast furnace rule: a recipe whose temperature is above the coils' (plus 100 K per voltage tier above MV) does not run. Each copy pays the full energy of both steps, so the hatches also bound the parallels. Batch mode is on.")
    add('emi.grindless.info.smelting_complex.4', "Needs, in any front-wall cell: 1 maintenance hatch, 1 muffler, 1 or 2 energy hatches, up to 2 input buses, 2 output buses, 4 input hatches and 4 output hatches (gases, coolant in, its return gas out); at least 64 heatproof casings there. 32 heating coils in two rings.")

    add('emi.grindless.info.tritium_removal_facility.0', "The Tritium Removal Facility de-tritiates heavy water. It works only on the Moon and needs a deuterium charge in the input hatch.")
    add('emi.grindless.info.tritium_removal_facility.1', "It is the source of tritium for the fusion fuel of later eras.")
    add('emi.grindless.info.tritium_removal_facility.2', "Takes the tritium out of the fission reactor's spent moderator, on the Moon. Catalytic exchange columns move the water's tritium into a deuterium carrier, and the cold box distils it off at cryogenic temperature. It only works on the Moon.")
    add('emi.grindless.info.tritium_removal_facility.3', "1,000 mB of tritiated heavy water gives 900 mB of heavy water back for the reactor and 200 mB of tritium, at 6,880 EU/t for 0.8 s. It needs a 100 mB deuterium charge in an input hatch: the carrier circulates inside and is never used up.")
    add('emi.grindless.info.tritium_removal_facility.4', "In the lunar night, with every radiator open to the sky, a run costs half: 3,440 EU/t. Each run keeps the price it started with. The tritium is kept for fusion: the facility refuses to void fluids.")
    add('emi.grindless.info.tritium_removal_facility.5', "Needs, in the lowest ring of the cold box: 1 or 2 energy hatches, 1 or 2 input hatches (the tritiated heavy water and the deuterium) and 1 or 2 output hatches (heavy water and tritium). ME hatches fit. It stands on sintered regolith, and nothing may cover the radiators.")

    add('emi.grindless.info.venus_acid_works.0', "The Venus Acid Works cracks sulfuric acid into water and oxygen. It works only on Venus, where acid is everywhere.")
    add('emi.grindless.info.venus_acid_works.1', "The water and oxygen are what Venus lacks for its own industry.")
    add('emi.grindless.info.venus_acid_works.2', "Water and oxygen from Venus's clouds: their sulfuric acid is cracked over a platinum gauze, and the planet's 737 K does the dehydration. Works only on Venus. The programmed circuit is the mode.")
    add('emi.grindless.info.venus_acid_works.3', "Each run: 1,000 mB of sulfuric acid, and the platinum gauze wears 0.1% -> 1,000 mB of distilled water + 1,000 mB of oxygen, for the energy of splitting that much water (45,000 EU). Circuit 1 returns the 1,000 mB of sulfur dioxide to Venus's air.")
    add('emi.grindless.info.venus_acid_works.4', "Circuit 2 keeps the sulfur dioxide (1,000 mB a run) for chemistry at home, where a chemical reactor turns it back into sulfur trioxide and sulfuric acid, and then refuses to void fluids. Each gas needs its own output hatch, or one ME output hatch takes them all.")
    add('emi.grindless.info.venus_acid_works.5', "8x11x5: a 5x5 plate of Venusian regolith on solid ground with an edge of inert casing; a 3x3x6 bayonet decomposer of titanium pipe casing round a PTFE pipe core; a desk with the controller; a 3x3x10 condenser stack of inert casing round a PTFE core, with eight heat vents, joined by a PTFE duct. Plate edge: 1-2 energy hatches, 1 input bus, 1 input hatch, 1-3 output hatches. ME parts fit.")

    add('emi.grindless.info.venus_heat_engine.0', "The Venus Heat Engine uses the heat of Venus: it burns nothing and gives 8,192 EU/t plus steam. It works only on Venus.")
    add('emi.grindless.info.venus_heat_engine.1', "Its EU leaves through dynamo hatches. The steam needs somewhere to go or it stops.")
    add('emi.grindless.info.venus_heat_engine.2', "Venus's own power: a hot plate on the 737 K ground and a radiator chimney rising towards the clouds, the cold side. Works only on Venus, and all the time: Venus is always at noon. It burns nothing.")
    add('emi.grindless.info.venus_heat_engine.3', "Each 20 s cycle: 200 mB of distilled water (the makeup of its working fluid) -> 8,192 EU/t and 32,000 mB of steam. Send the steam to a turbine through an output hatch, or set the controller to void fluids.")
    add('emi.grindless.info.venus_heat_engine.4', "Its EU leaves through dynamo hatches: one IV dynamo hatch, or two EV ones, carries it all. The Venus Acid Works makes its water from the clouds.")
    add('emi.grindless.info.venus_heat_engine.5', "5x16x5: a 5x5 footing of Venusian regolith on solid ground; an engine house of robust tungstensteel casing round a 3x3 hot plate of tungstensteel fireboxes with a tungstensteel gearbox above it; a roof, and an 11-block tungstensteel pipe riser with four night-sky radiators on every block. House walls: 1-2 dynamo hatches, 1 input hatch, up to 1 output hatch.")
})

ClientEvents.lang('es_es', event => {
    var add = function (key, value) { event.add('grindless', key, value) }

    add('emi.grindless.info.fission_reactor.0', "El reactor de fisión convierte combustible nuclear en EU y calor. Circuito 1: uranio poco enriquecido con agua ligera. Circuito 2: el mismo combustible con agua pesada. Circuito 3: MOX con agua pesada. Circuito 4: criador, que fabrica plutonio.")
    add('emi.grindless.info.fission_reactor.1', "Si su salida no tiene adónde ir, el reactor hace SCRAM: se detiene con seguridad en vez de eliminar. El combustible gastado va a la celda caliente para reprocesarse.")
    add('emi.grindless.info.fission_reactor.2', "Un reactor de fisión de núcleo diseñado: los elementos combustibles de cuatro canales de acero de tungsteno hierven agua para una sala de turbinas. No quema nada, así que funciona en cualquier sitio. El circuito programado elige el núcleo: 1 LEU con agua ligera, 2 LEU con agua pesada, 3 MOX con agua pesada, 4 reproductor.")
    add('emi.grindless.info.fission_reactor.3', "Por canal y ciclo de 20 s: 2000 mB de agua, que se pierden por los respiraderos. El LEU con agua ligera da 16 384 EU/t; con agua pesada, 32 768, y 5 mB de agua pesada salen tritiados; el MOX con agua pesada, lo mismo; el reproductor, 8192, y su elemento gastado lleva más plutonio del que entró.")
    add('emi.grindless.info.fission_reactor.4', "Un elemento se desgasta un 0,5 % por ciclo: se gasta uno, y sale un elemento gastado, cada 200 ciclos de canal (unos 67 min en un canal). Canales = el menor de 4, los elementos de los buses, el agua y el agua pesada, el sitio para lo que sale y las escotillas dinamo (un canal de agua pesada pide 32 768 EU/t: una escotilla IV de 4 A; una de 16 A lleva los cuatro).")
    add('emi.grindless.info.fission_reactor.5', "SCRAM, no explosión: sin agua, o sin sitio para el combustible gastado o el agua pesada tritiada, acaba su ciclo y se para sin perder nada; no acepta tirar nada. Suelo de la sala de turbinas: 1-2 buses de entrada, 1-2 buses de salida, 1-3 escotillas de entrada de fluidos, hasta 1 escotilla de salida de fluidos y 1-4 escotillas dinamo. Valen las piezas ME.")

    add('emi.grindless.info.fluorspar_kiln.0', "El horno de fluorita calienta fluorita con ácido sulfúrico y agua y da ácido fluorhídrico y yeso. De aquí sale el ácido fluorhídrico de la línea nuclear.")
    add('emi.grindless.info.fluorspar_kiln.1', "El yeso es un subproducto inofensivo: se puede eliminar o usar para construir.")
    add('emi.grindless.info.fluorspar_kiln.2', "Un horno rotatorio largo sobre estaciones de rodillos, movido por una caja de engranajes, con un lavador de HF en su extremo caliente. La fluorita, el ácido sulfúrico y el agua entran por el extremo frío: el ácido fluorhídrico sale del lavador, y el sulfato de calcio se apaga con el agua y cae como yeso. La fluorita que no reacciona vuelve a la alimentación.")
    add('emi.grindless.info.fluorspar_kiln.3', "Hace muchas cargas a la vez, cada una con la potencia y el tiempo de la receta, sin overclock: tantas como permiten las entradas, el sitio libre y las escotillas de energía, hasta 256. Una escotilla de energía IV mueve las 256.")
    add('emi.grindless.info.fluorspar_kiln.4', "El HF alimenta la planta de naquadah, el enriquecimiento de la celda caliente y el PTFE; el yeso va al hormigón. El lavador guarda hasta la última gota de HF: el horno no acepta tirar fluidos. El yeso que sobra es inerte y se puede tirar.")
    add('emi.grindless.info.fluorspar_kiln.5', "Cabezal de alimentación, alrededor del controlador: 1-2 escotillas de energía, 1-2 buses de entrada y 1-4 escotillas de entrada (ácido y agua). Lavador, las dos filas bajas de su muro trasero y la fila bajo el horno: 1-2 buses de salida y 1-2 escotillas de salida. Valen las piezas ME.")

    add('emi.grindless.info.fuel_fabrication_plant.0', "La planta de fabricación de combustible construye ensamblajes de combustible. Circuito 1: pastillas de combustible. Circuito 2: tubos de revestimiento. Circuito 3: el ensamblaje de uranio poco enriquecido que quema el reactor de fisión.")
    add('emi.grindless.info.fuel_fabrication_plant.1', "Es el paso entre el uranio enriquecido y el reactor.")
    add('emi.grindless.info.fuel_fabrication_plant.2', "Combustible de verdad: pastillas de dióxido de uranio en tubos de zircaloy, rellenos de helio. El circuito programado elige el paso: 1 pastillas, 2 tubos de vaina, 3 el elemento combustible de LEU.")
    add('emi.grindless.info.fuel_fabrication_plant.3', "1: 1 de U-235 + 9 de polvo de U-238 + 20 000 mB de oxígeno -> 10 pastillas de LEU, prensadas y sinterizadas en hidrógeno. Deja 500 mB de hidrógeno en una escotilla: da vueltas dentro del horno y no se gasta.")
    add('emi.grindless.info.fuel_fabrication_plant.4', "2: 1 lingote de zircaloy -> 2 tubos de vaina en el laminador de paso peregrino. 3: 10 pastillas + 4 tubos + 100 mB de helio -> 1 elemento combustible de LEU, el combustible del reactor de fisión.")
    add('emi.grindless.info.fuel_fabrication_plant.5', "Una línea de 3x4x13 de carcasa limpia de acero inoxidable: prensa de pastillas, túnel de sinterizado con dos anillos de bobinas de kanthal o más calientes, banco del laminador sobre una bancada de armazones de acero de tungsteno y una caja de guantes de vidrio laminado. Suelo de la prensa y de la caja de guantes: 1-3 buses de entrada, 1-2 buses de salida, 1-4 escotillas de entrada de fluidos y 1-2 escotillas de energía. Valen las piezas ME.")

    add('emi.grindless.info.heavy_water_plant.0', "La planta de agua pesada concentra deuterio a partir de agua. Circuito 1: intercambio isotópico. Circuito 2: acabado a agua pesada. Circuito 3: modo Proxima, desde UHV.")
    add('emi.grindless.info.heavy_water_plant.1', "Necesita una carga de sulfuro de hidrógeno para el intercambio. El agua pesada alimenta el reactor de fisión y la línea del tritio.")
    add('emi.grindless.info.heavy_water_plant.2', "Una planta de sulfuro de Girdler: una torre fría y una torre caliente más alta unidas por un puente intercambiador de calor, y una columna de vacío. El hielo marciano rico en deuterio entra en polvo y se funde dentro. El circuito programado elige el modo: 1 intercambio, 2 acabado, 3 intercambio del agua enriquecida en deuterio de Próxima b (UHV).")
    add('emi.grindless.info.heavy_water_plant.3', "Intercambio: 16 de hielo y 25 600 mB de vapor dan 3200 mB de concentrado de agua pesada, 12 800 mB de agua empobrecida y 160 mB de agua destilada. Necesita una carga de 1000 mB de sulfuro de hidrógeno en una escotilla de entrada propia: la carga circula entre las torres y nunca se gasta.")
    add('emi.grindless.info.heavy_water_plant.4', "Acabado: 1000 mB de concentrado dan 200 mB de agua pesada y 800 mB de agua destilada. Un hielo da 40 mB de agua pesada: el moderador del reactor de fisión, y 80 mB de deuterio en el electrolizador.")
    add('emi.grindless.info.heavy_water_plant.5', "Los pies de las torres admiten 1-2 escotillas de energía, 1-2 buses de entrada, 1-4 escotillas de entrada y 1-4 escotillas de salida; valen las piezas ME. El vapor viene de plantas que nunca tiran el suyo: la planta de ciclo combinado y el tren de laminación en caliente. El agua empobrecida es agua normal.")

    add('emi.grindless.info.hot_cell.0', "La celda caliente maneja material radiactivo tras un blindaje. Circuito 1: enriquecimiento. 2: combustible. 3: reprocesado de combustible gastado. 4: radón. 5: silicio-28. 6: boro-11. 7: níquel-62.")
    add('emi.grindless.info.hot_cell.1', "Se niega a eliminar: si una salida está bloqueada se detiene. El reprocesado es lo que devuelve algo del combustible gastado.")
    add('emi.grindless.info.hot_cell.2', "Un banco de dos celdas blindadas: el material radiactivo entra por buses y escotillas y sale a la red, nunca pasa por las manos. Unas pinzas que atraviesan el muro sobre cada ventana de vidrio plomado hacen el trabajo. El circuito programado elige el modo: 1 enriquecimiento, 2 combustible, 3 reprocesado, 4 radón, 5 silicio-28, 6 boro-11, 7 níquel-62.")
    add('emi.grindless.info.hot_cell.3', "Los modos 1 y 4 hacen las líneas de GregTech en una pasada, con la misma energía: el enriquecimiento convierte 30 de uraninita y 40 000 mB de HF en 1 de U-235, 9 de U-238, agua y el mismo flúor como F2, y el UF6 nunca sale; el radón no pide plutonio, porque el catalizador de plutonio de GregTech se queda dentro.")
    add('emi.grindless.info.hot_cell.4', "El modo 2 hace elementos MOX y reproductores en tubos de zircaloy, pastillas de RTG y fuentes de neutrones de Pu-Be. El modo 3 reprocesa elementos gastados en ácido nítrico: vuelven el uranio y el plutonio, con xenón, kriptón, cesio, neodimio, NO2 para el ácido nítrico y residuo vitrificado.")
    add('emi.grindless.info.hot_cell.5', "El residuo queda confinado: sale por el bus de salida, y la celda no acepta tirar nada. Muro de servicio y muros laterales: 1-2 escotillas de energía, 1-3 buses de entrada, 1-3 buses de salida, 1-4 escotillas de entrada y 1-4 escotillas de salida. Valen las piezas ME.")

    add('emi.grindless.info.interferometer.0', "El interferómetro es una red de telescopios en Mercurio que solo funciona de noche. Escribe la Carta del Sistema Exterior en memorias y orbes de datos.")
    add('emi.grindless.info.interferometer.1', "Es la única fuente de esa carta. Al amanecer espera y conserva su progreso.")
    add('emi.grindless.info.interferometer.2', "Tres antenas parabólicas de acero de tungsteno sobre pedestales de ladrillo, unidas por un tendido de cable a una caseta correladora: un interferómetro de radio en Mercurio, con la antena de espacio profundo de la Luna en el otro extremo de su línea de base.")
    add('emi.grindless.info.interferometer.3', "Solo funciona en Mercurio y de noche. Si amanece a medio ciclo, espera y no pierde lo hecho.")
    add('emi.grindless.info.interferometer.4', "Añade la mitad de Mercurio a una grabación VLBI lunar y escribe la carta del sistema exterior (calibrada por la carta de los planetas interiores, que no se gasta) o, calibrada por la carta del sistema exterior, la primera señal de Sagitario A*.")
    add('emi.grindless.info.interferometer.5', "Necesita, en la caseta correladora: 1 o 2 escotillas de energía (IV), 1 bus de entrada y 1 bus de salida.")

    add('emi.grindless.info.isr_wellfield.0', "El campo de pozos ISR lixivia uranio in situ en el End: ácido sulfúrico y oxígeno bajan por los pozos y sube uraninita.")
    add('emi.grindless.info.isr_wellfield.1', "Solo funciona en el End. La uraninita alimenta la línea del uranio hacia el enriquecimiento.")
    add('emi.grindless.info.isr_wellfield.2', "Uranio sin broca: el ácido sulfúrico y el oxígeno bajan por cuatro pozos de inyección, disuelven el uranio de la veta de pechblenda del End en su sitio, y el pozo de producción lo sube a la caseta de cabecera, donde el intercambio iónico lo atrapa. Solo funciona en el End.")
    add('emi.grindless.info.isr_wellfield.3', "Cada tanda: la muestra de la veta (no se gasta) + 100 mB de ácido sulfúrico + 50 mB de oxígeno, y la resina de intercambio iónico se desgasta un 1 % -> 2 de polvo de uraninita. El torio y el plomo se quedan en el suelo.")
    add('emi.grindless.info.isr_wellfield.4', "El radio que arrastra la solución sale como residuo radiactivo (un 1 % de las tandas): se guarda, así que el campo no acepta tirar objetos.")
    add('emi.grindless.info.isr_wellfield.5', "Un cinco puntos de 7x7: pozos de carcasa de tubería de acero de tungsteno que bajan tres bloques bajo tierra, con cabezales de tubería de PTFE y un armazón de acero de tungsteno encima, y una caseta de cabecera de carcasa inerte con dos columnas de intercambio iónico. Paredes de la caseta: 1-2 buses de entrada, 1-2 buses de salida, 1-3 escotillas de entrada de fluidos y 1-2 escotillas de energía. Valen las piezas ME.")

    add('emi.grindless.info.mercury_solar_field.0', "El campo solar de Mercurio convierte la luz solar de Mercurio en EU. Pon el circuito programado 1 en el bus de entrada.")
    add('emi.grindless.info.mercury_solar_field.1', "Solo funciona en Mercurio y solo de día; de noche espera sin perder nada. Su EU sale por escotillas dinamo.")
    add('emi.grindless.info.mercury_solar_field.2', "36 paneles de película fina de Mercurio sobre postes de acero de tungsteno y ladrillos de escudo térmico, una batería de radiadores detrás y la caseta de control bajo un parasol de ladrillos. La luz del sol pasa directa a EU.")
    add('emi.grindless.info.mercury_solar_field.3', "Solo funciona de día, en Mercurio (luz solar x6,7: 2.010 EU/t por panel). Cada uno de sus 36 paneles con el cielo abierto encima suma un ciclo: 72.360 EU/t. De noche espera, sin perder nada.")
    add('emi.grindless.info.mercury_solar_field.4', "Pon el circuito programado 1 en el bus de entrada. Ciclos = el menor de los paneles iluminados y lo que llevan las escotillas dinamo (una escotilla dinamo IV lleva 16.384 EU/t: 8 paneles; tres escotillas IV de 4 A llevan el campo entero).")
    add('emi.grindless.info.mercury_solar_field.5', "Necesita, en la caseta de control: 1 bus de entrada y de 1 a 4 escotillas dinamo. De noche, usa baterías o la energía de casa a través del puente de AE2.")

    add('emi.grindless.info.mercury_solar_works.0', "La fábrica solar de Mercurio es la fábrica del planeta. Sinteriza ladrillos de escudo térmico, fabrica paneles solares de película fina y funde iridosmina.")
    add('emi.grindless.info.mercury_solar_works.1', "Solo funciona en Mercurio. Los ladrillos revisten las estructuras de Mercurio; la iridosmina va a la planta de platino.")
    add('emi.grindless.info.mercury_solar_works.2', "El taller de Mercurio: ocho espejos heliostatos concentran el sol en un horno focal de acero de tungsteno robusto, con una campana de evaporación de vidrio laminado al lado. Solo funciona en Mercurio.")
    add('emi.grindless.info.mercury_solar_works.3', "Sinteriza polvo de regolito de Mercurio en ladrillos de escudo térmico, evapora arseniuro de galio sobre obleas de silicio en paneles de película fina y funde iridosmina con salitre y agua salada en mezcla de metales rarísimos y tetróxido de osmio (3 de iridio por 1 de osmio, refinados en casa).")
    add('emi.grindless.info.mercury_solar_works.4', "Regla del sol: un ciclo que empieza con el sol en el receptor y los ocho espejos bajo el cielo abierto paga una cuarta parte de su EU/t; de noche o a la sombra lo paga entero. Más barato, nunca más rápido.")
    add('emi.grindless.info.mercury_solar_works.5', "Necesita 1 o 2 escotillas de energía, 1 o 2 buses de entrada, 1 o 2 buses de salida, hasta 1 escotilla de entrada y hasta 2 de salida. Hace los ladrillos, así que su base es roca de Mercurio. Mientras vacía fluidos, la fusión no funciona: el tetróxido de osmio se guarda.")

    add('emi.grindless.info.mercury_vein_drill.0', "La perforadora de vetas de Mercurio perfora las vetas de Mercurio, solo allí, y nunca una veta de la Tierra. Pon la muestra y brocas de acero de tungsteno en el bus de entrada.")
    add('emi.grindless.info.mercury_vein_drill.1', "El nitrógeno líquido en la escotilla de entrada da más mena y menos desgaste de broca de día.")
    add('emi.grindless.info.mercury_vein_drill.2', "La perforadora de vetas de Mercurio: un cuerpo bajo de ladrillos de escudo térmico bajo un parasol de ladrillos sobre cuatro postes de acero de tungsteno, con radiadores colgados bajo el parasol y una sarta de perforación hasta la corteza. Solo perfora las vetas de Mercurio, y solo en Mercurio.")
    add('emi.grindless.info.mercury_vein_drill.3', "Broca de acero de tungsteno, 5,625 menas en bruto por ciclo. De día solo funciona con nitrógeno líquido (10 mB por ciclo, y la broca se gasta en cerca del 0,25 % de los ciclos): el sol de Mercurio quemaría una broca en seco. De noche perfora en seco y guarda el nitrógeno, pero la broca se gasta el doble de rápido (0,5 %).")
    add('emi.grindless.info.mercury_vein_drill.4', "Hace tantos ciclos a la vez como permitan sus escotillas de energía (voltaje / 8 EU/t, hasta 128, una broca por ciclo): una escotilla IV llena los 128 y reduce el tiempo a la mitad. El día o la noche se leen al empezar cada ciclo, así que el amanecer y el anochecer nunca paran un ciclo a medias.")
    add('emi.grindless.info.mercury_vein_drill.5', "Necesita 1 o 2 escotillas de energía, 1 bus de entrada (muestra y brocas), 1 o 2 buses de salida y 1 escotilla de entrada para el nitrógeno líquido; valen los buses y escotillas ME. Se apoya en ladrillos de escudo térmico de Mercurio.")

    add('emi.grindless.info.naquadah_plant.0', "La planta de naquadah refina naquadah. El circuito 1 ejecuta la línea del naquadah; los circuitos 2 y 3 son modos LuV.")
    add('emi.grindless.info.naquadah_plant.1', "Necesita una fuente de neutrones de plutonio-berilio. Sus productos alimentan los materiales densos de las siguientes eras.")
    add('emi.grindless.info.naquadah_plant.2', "La línea del naquadah de GT-- en una planta. Su activador de neutrones solo da naquadah mientras su energía de neutrones está en una ventana estrecha, que se mantiene con aceleradores y un sensor; aquí una fuente de neutrones de Pu-Be en el bus de entrada mantiene la ventana, y el ácido fluoroantimónico, el superácido más fuerte que se conoce, se hace y se gasta dentro.")
    add('emi.grindless.info.naquadah_plant.3', "Circuito 1: 4 de mezcla de óxidos de naquadah, 15 de trióxido de antimonio y 40 500 mB de ácido fluorhídrico dan 2 de polvo de naquadah, titanio y galio (cada uno en la mitad de los lotes), 10 500 mB de hidrógeno y 9 000 mB de agua. La fuente de Pu-Be se gasta en el 1 % de los lotes.")
    add('emi.grindless.info.naquadah_plant.4', "Mismas proporciones y misma energía que las máquinas de GT--, el mantenimiento de los aceleradores incluido (unos 1,14 millones de EU por lote), gastada a un máximo de 7 680 EU/t; los modos 2 y 3, a un máximo de 30 720 EU/t (LuV).")
    add('emi.grindless.info.naquadah_plant.5', "Nave del superácido: 1-2 escotillas de energía (dos escotillas EV la mueven hasta que el iridio de Mercurio permite las IV), 1-2 buses de entrada, 1-2 buses de salida, 1-6 escotillas de entrada y 1-4 escotillas de salida en sus bordes; la cámara de activación de carcasa a prueba de radiación está a su lado. Valen las piezas ME.")
    add('emi.grindless.info.naquadah_plant.6', "LuV, circuito 2: 4 de mezcla de óxidos de naquadah enriquecido, 36 000 mB de flúor, 26 500 mB de hidrógeno y 8 000 mB de ácido sulfúrico dan sulfato de naquadah enriquecido, 2 de sulfuro de trinio, solución impura de naquadria, titanio y HF. El xenón, el ácido fluoroantimónico, el trifluoruro de oro y el catalizador de Pd/C se quedan en las escotillas y el bus como cargas. El circuito 3 hace lo mismo con 6 de polvo de naquadah de barras gastadas de reactor. Ninguno de los dos desecha lo que produce.")

    add('emi.grindless.info.pressurized_vein_drill.0', "La perforadora de vetas presurizada perfora la veta de naquadah de Venus y las vetas de Marte, cada una solo en su mundo.")
    add('emi.grindless.info.pressurized_vein_drill.1', "Es la perforadora para los lugares donde la perforadora trípode EV no aguanta la presión.")
    add('emi.grindless.info.pressurized_vein_drill.2', "El paso IV de la familia de perforadoras de vetas, para Venus y Marte: un pozo cerrado contra 92 bar, con camisa de acero de tungsteno, bajo una carcasa de presión de carcasa inerte y una plataforma de filtros de polvo. Hasta 128 pasadas a la vez, una broca de acero de tungsteno por pasada en el bus de entrada (un 0,25 % de desgaste por pasada).")
    add('emi.grindless.info.pressurized_vein_drill.3', "Venus: la veta de naquadah, muy honda bajo los mares de lava. Cada pasada: la muestra de la veta (no se gasta) + 200 mB de agua destilada, el impuesto del calor -> 5,625 menas en bruto, adoquín de Venus y 1600 mB de vapor. El vapor es inerte: mándalo a una turbina por una escotilla de salida, o pon el controlador a tirar fluidos.")
    add('emi.grindless.info.pressurized_vein_drill.4', "Marte: sus tres vetas, en seco, porque los filtros de polvo mantienen limpia la broca. Cada pasada: la muestra de la veta + la broca -> 5,625 menas en bruto y adoquín marciano. En ningún otro sitio perfora nada.")
    add('emi.grindless.info.pressurized_vein_drill.5', "5x9x4: una base de 5x4 de regolito venusiano sobre suelo firme alrededor de una sarta de carcasa de tubería de acero de tungsteno, una carcasa de 3x3x3 de carcasa inerte, una plataforma de 3x3 de carcasas de filtro y un armazón de acero de tungsteno sobre la sarta. Carcasa: 1-2 escotillas de energía, 1 bus de entrada, 1-2 buses de salida, hasta 1 escotilla de entrada y hasta 1 de salida. Valen las piezas ME.")

    add('emi.grindless.info.smelting_complex.0', "El complejo de fundición es un alto horno y un congelador de vacío en uno. Ejecuta recetas de alto horno y el paso del congelador en una sola pasada.")
    add('emi.grindless.info.smelting_complex.1', "Sus bobinas fijan cuántas copias corren a la vez, así que es la vía de alto rendimiento para hacer lingotes de aleación.")
    add('emi.grindless.info.smelting_complex.2', "Un horno de alta temperatura y un congelador de vacío en una nave: una cámara de bobinas para el calor, una cámara fría para el enfriado y un mamparo de acero de tungsteno entre ambas. Una receta por cada receta del horno que da un lingote caliente, con el paso del congelador incluido: polvos y gas de entrada, el lingote enfriado, los subproductos y el gas de retorno del refrigerante como salidas.")
    add('emi.grindless.info.smelting_complex.3', "Las bobinas fijan los paralelos (2^(temperatura de la bobina / 900), hasta 64) y la regla del horno de GTM: una receta cuya temperatura supera la de las bobinas (más 100 K por tier de voltaje sobre MV) no corre. Cada copia paga la energía completa de los dos pasos, así que las escotillas también limitan los paralelos. El modo por lotes está activo.")
    add('emi.grindless.info.smelting_complex.4', "Necesita, en cualquier celda de la pared frontal: 1 escotilla de mantenimiento, 1 silenciador, 1 o 2 escotillas de energía, hasta 2 buses de entrada, 2 de salida, 4 escotillas de entrada y 4 de salida (gases, refrigerante de entrada, su gas de retorno de salida); al menos 64 carcasas termorresistentes allí. 32 bobinas calefactoras en dos anillos.")

    add('emi.grindless.info.tritium_removal_facility.0', "La instalación de retirada de tritio destritia agua pesada. Solo funciona en la Luna y necesita una carga de deuterio en la escotilla de entrada.")
    add('emi.grindless.info.tritium_removal_facility.1', "Es la fuente de tritio para el combustible de fusión de las eras posteriores.")
    add('emi.grindless.info.tritium_removal_facility.2', "Saca el tritio del moderador gastado del reactor de fisión, en la Luna. Las columnas de intercambio catalítico pasan el tritio del agua a un portador de deuterio, y la caja fría lo separa por destilación criogénica. Solo funciona en la Luna.")
    add('emi.grindless.info.tritium_removal_facility.3', "1000 mB de agua pesada tritiada devuelven 900 mB de agua pesada al reactor y dan 200 mB de tritio, a 6880 EU/t durante 0,8 s. Necesita una carga de 100 mB de deuterio en una escotilla de entrada: el portador circula dentro y nunca se gasta.")
    add('emi.grindless.info.tritium_removal_facility.4', "En la noche lunar, con todos los radiadores abiertos al cielo, cada ciclo cuesta la mitad: 3440 EU/t. Cada ciclo conserva el precio con el que empezó. El tritio se guarda para la fusión: la planta no deja vaciar fluidos.")
    add('emi.grindless.info.tritium_removal_facility.5', "Necesita, en el anillo más bajo de la caja fría: 1 o 2 escotillas de energía, 1 o 2 escotillas de entrada (el agua pesada tritiada y el deuterio) y 1 o 2 escotillas de salida (agua pesada y tritio). Valen escotillas ME. Se apoya en regolito sinterizado, y nada puede tapar los radiadores.")

    add('emi.grindless.info.venus_acid_works.0', "La planta de ácido de Venus descompone ácido sulfúrico en agua y oxígeno. Solo funciona en Venus, donde el ácido abunda.")
    add('emi.grindless.info.venus_acid_works.1', "El agua y el oxígeno son lo que a Venus le falta para su propia industria.")
    add('emi.grindless.info.venus_acid_works.2', "Agua y oxígeno de las nubes de Venus: su ácido sulfúrico se craquea sobre una malla de platino, y los 737 K del planeta hacen la deshidratación. Solo funciona en Venus. El circuito programado es el modo.")
    add('emi.grindless.info.venus_acid_works.3', "Cada pasada: 1000 mB de ácido sulfúrico, y la malla de platino se desgasta un 0,1 % -> 1000 mB de agua destilada + 1000 mB de oxígeno, por la energía de partir esa misma agua (45 000 EU). El circuito 1 devuelve los 1000 mB de dióxido de azufre al aire de Venus.")
    add('emi.grindless.info.venus_acid_works.4', "El circuito 2 guarda el dióxido de azufre (1000 mB por pasada) para la química de casa, donde un reactor químico lo vuelve a convertir en trióxido de azufre y ácido sulfúrico, y entonces no acepta tirar fluidos. Cada gas necesita su propia escotilla de salida, o una escotilla de salida ME los recoge todos.")
    add('emi.grindless.info.venus_acid_works.5', "8x11x5: una placa de 5x5 de regolito venusiano sobre suelo firme con un borde de carcasa inerte; un descomponedor de bayoneta de 3x3x6 de carcasa de tubería de titanio alrededor de un núcleo de tubería de PTFE; un pupitre con el controlador; una columna de condensación de 3x3x10 de carcasa inerte alrededor de un núcleo de PTFE, con ocho rejillas de calor, unida por un conducto de PTFE. Borde de la placa: 1-2 escotillas de energía, 1 bus de entrada, 1 escotilla de entrada, 1-3 escotillas de salida. Valen las piezas ME.")

    add('emi.grindless.info.venus_heat_engine.0', "El motor térmico de Venus aprovecha el calor de Venus: no quema nada y da 8.192 EU/t más vapor. Solo funciona en Venus.")
    add('emi.grindless.info.venus_heat_engine.1', "Su EU sale por escotillas dinamo. El vapor necesita adónde ir o se detiene.")
    add('emi.grindless.info.venus_heat_engine.2', "La energía propia de Venus: una placa caliente sobre el suelo a 737 K y una chimenea de radiadores que sube hacia las nubes, el lado frío. Solo funciona en Venus, y a todas horas: en Venus siempre es mediodía. No quema nada.")
    add('emi.grindless.info.venus_heat_engine.3', "Cada ciclo de 20 s: 200 mB de agua destilada (la reposición de su fluido de trabajo) -> 8192 EU/t y 32 000 mB de vapor. Manda el vapor a una turbina por una escotilla de salida, o pon el controlador a tirar fluidos.")
    add('emi.grindless.info.venus_heat_engine.4', "Su energía sale por escotillas dínamo: una escotilla dínamo IV, o dos EV, la llevan toda. La planta de ácido de Venus saca su agua de las nubes.")
    add('emi.grindless.info.venus_heat_engine.5', "5x16x5: una zapata de 5x5 de regolito venusiano sobre suelo firme; una casa del motor de carcasa robusta de acero de tungsteno alrededor de una placa caliente de 3x3 de hogares de acero de tungsteno con una caja de engranajes de acero de tungsteno encima; un tejado, y un tubo ascendente de 11 bloques de carcasa de tubería de acero de tungsteno con cuatro radiadores de cielo nocturno en cada bloque. Paredes: 1-2 escotillas dínamo, 1 escotilla de entrada, hasta 1 de salida.")
})
